"""
Visualization: Tropical Kernel Dimension Landscape

This script creates a heatmap showing how the tropical kernel dimension
varies across different basepoint choices and filtration stages for a
fixed graph. It reveals the basepoint-sensitivity of the tropical
persistence barcode.
"""

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from collections import defaultdict
from typing import NamedTuple

class UnionFind:
    def __init__(self, elements):
        self.parent = {x: x for x in elements}
        self.rank = {x: 0 for x in elements}
    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry: return False
        if self.rank[rx] < self.rank[ry]: rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]: self.rank[rx] += 1
        return True
    def components(self):
        comp = defaultdict(set)
        for x in self.parent: comp[self.find(x)].add(x)
        return dict(comp)

class Graph:
    def __init__(self, vertices, edges):
        self.vertices = set(vertices)
        self.edges = set()
        self.adj = defaultdict(set)
        for u, v in edges:
            if u != v and u in vertices and v in vertices:
                edge = (min(u, v), max(u, v))
                self.edges.add(edge)
                self.adj[u].add(v)
                self.adj[v].add(u)
    def neighbors(self, v): return self.adj[v]
    def induced_subgraph(self, S):
        sub_edges = {(u, v) for u, v in self.edges if u in S and v in S}
        return Graph(S, sub_edges)

class TropicalFiltrationEvent(NamedTuple):
    cycle_birth: int
    q_visible_birth: int
    invisible_merge_death: int
    @property
    def delta(self): return self.cycle_birth + self.q_visible_birth - self.invisible_merge_death

def induced_edge_count(G, S):
    return sum(1 for u, v in G.edges if u in S and v in S)

def induced_component_count(G, S):
    if not S: return 0
    uf = UnionFind(S)
    for u, v in G.edges:
        if u in S and v in S: uf.union(u, v)
    return len(uf.components())

def induced_cycle_rank(G, S):
    if not S: return 0
    return induced_edge_count(G, S) + induced_component_count(G, S) - len(S)

def q_visible_component_count(G, q, S):
    if not S: return 0
    uf = UnionFind(S)
    for u, v in G.edges:
        if u in S and v in S: uf.union(u, v)
    comps = uf.components()
    count = 0
    for root, members in comps.items():
        for v in members:
            if q in G.neighbors(v):
                count += 1
                break
    return count

def tropical_kernel_dim(G, q, S):
    return induced_cycle_rank(G, S) + q_visible_component_count(G, q, S)

def compute_step_event(G, q, S, v):
    S_new = S | {v}
    cr_old = induced_cycle_rank(G, S)
    cr_new = induced_cycle_rank(G, S_new)
    qv_old = q_visible_component_count(G, q, S)
    qv_new = q_visible_component_count(G, q, S_new)
    return TropicalFiltrationEvent(
        max(cr_new - cr_old, 0), max(qv_new - qv_old, 0),
        max(cr_old - cr_new, 0) + max(qv_old - qv_new, 0))

def compute_tropical_barcode(G, q, filtration):
    events = []
    for k in range(len(filtration) - 1):
        S_k, S_k1 = filtration[k], filtration[k + 1]
        new_vertices = S_k1 - S_k
        if len(new_vertices) == 1:
            events.append(compute_step_event(G, q, S_k, next(iter(new_vertices))))
        else:
            cr_old = induced_cycle_rank(G, S_k)
            cr_new = induced_cycle_rank(G, S_k1)
            qv_old = q_visible_component_count(G, q, S_k)
            qv_new = q_visible_component_count(G, q, S_k1)
            events.append(TropicalFiltrationEvent(
                max(cr_new - cr_old, 0), max(qv_new - qv_old, 0),
                max(cr_old - cr_new, 0) + max(qv_old - qv_new, 0)))
    return events

def compute_dims(G, q, filtration):
    return [tropical_kernel_dim(G, q, S) for S in filtration]

def reconstruct_dims(init, events):
    dims = [init]
    current = init
    for e in events:
        current += e.delta
        dims.append(current)
    return dims

def verify_barcode_correctness(G, q, filtration):
    direct = compute_dims(G, q, filtration)
    events = compute_tropical_barcode(G, q, filtration)
    reconstructed = reconstruct_dims(direct[0] if direct else 0, events)
    return direct == reconstructed, direct, reconstructed

def graph_h1_rank_delta(G, filtration, k):
    return induced_cycle_rank(G, filtration[k+1]) - induced_cycle_rank(G, filtration[k])

def complete_graph(n):
    return Graph(set(range(n)), {(i, j) for i in range(n) for j in range(i+1, n)})

def cycle_graph(n):
    return Graph(set(range(n)), {(i, (i+1) % n) for i in range(n)})

def path_graph(n):
    return Graph(set(range(n)), {(i, i+1) for i in range(n-1)})

def star_graph(n):
    return Graph(set(range(n)), {(0, i) for i in range(1, n)})

def petersen_graph():
    V = set(range(10))
    outer = {(i, (i+1) % 5) for i in range(5)}
    inner = {(5 + i, 5 + (i+2) % 5) for i in range(5)}
    spokes = {(i, i+5) for i in range(5)}
    return Graph(V, outer | inner | spokes)

# Build a moderately interesting graph
# Petersen-like: 8 vertices with mixed connectivity
V = set(range(8))
E = {
    (0, 1), (1, 2), (2, 3), (3, 0),  # outer square
    (4, 5), (5, 6), (6, 7), (7, 4),  # inner square
    (0, 4), (1, 5), (2, 6), (3, 7),  # connecting spokes
}
G = Graph(V, E)

# For each basepoint q, compute dimension sequence along canonical filtration
n = len(V)
basepoints = list(range(n))

# Use a canonical filtration that adds vertices 0,1,...,n-1 (excluding q)
dim_matrix = np.zeros((n, n), dtype=int)  # basepoint x filtration_step
cr_matrix = np.zeros((n, n), dtype=int)
qv_matrix = np.zeros((n, n), dtype=int)

for qi, q in enumerate(basepoints):
    available = sorted(V - {q})
    filt = [set()]
    for v in available:
        filt.append(filt[-1] | {v})

    for step, S in enumerate(filt):
        if step < n:
            dim_matrix[qi, step] = tropical_kernel_dim(G, q, S)
            cr_matrix[qi, step] = induced_cycle_rank(G, S)
            qv_matrix[qi, step] = q_visible_component_count(G, q, S)

fig, axes = plt.subplots(1, 3, figsize=(18, 6))

# Tropical kernel dimension
im0 = axes[0].imshow(dim_matrix, cmap='YlOrRd', aspect='auto', interpolation='nearest')
axes[0].set_title('Tropical Kernel Dimension δ(S)', fontsize=14, fontweight='bold')
axes[0].set_xlabel('Filtration Step')
